#include "WCP2dToy/TimeKeeper.h"

#include <sstream>
#include <iostream>		// debugging

using namespace std;
using namespace WCP;

/**
 * Constructor for TimeKeeper class, initializes time keeping with a message and starting time.
 *
 * @param msg Message associated with the start of time keeping.
 * @param starting_time Initial time point for time tracking.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
TimeKeeper::TimeKeeper(const std::string& msg, ptime starting_time)
{
    //cerr << "TimeKeeper starting with \"" << msg << "\"" << endl;
    m_events.push_back(event(starting_time, msg));
}

TimeKeeper::~TimeKeeper()
{
}

/**
 * @brief Processes a message and records the current time 
 * @param msg Message to be processed
 * @param now Current time
 * @return Result of emitting the event
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
std::string TimeKeeper::operator()(std::string msg, ptime now)
{
    //cerr << "TimeKeeper: accepting message: " << msg << endl;
    m_events.push_back(event(now, msg));
    return emit(-1);
}

/**
 * Returns the start time of the TimeKeeper object.
 *
 * @return The start time as a boost::posix_time::ptime object.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
boost::posix_time::ptime TimeKeeper::start_time() const
{
    return (*this)[0].first;
}
/**
 * Returns the last recorded time 
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
boost::posix_time::ptime TimeKeeper::last_time() const
{
    return (*this)[-1].first;
}
/**
 * @brief Returns the duration of the last time interval.
 *
 * Calculates the difference between the start times of the last two recorded events.
 *
 * @return The duration of the last time interval.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
TimeKeeper::deltat TimeKeeper::last_duration() const
{
    return (*this)[-1].first - (*this)[-2].first;
}

/**
 * Returns the time duration since the start time.
 *
 * @param now The current time point.
 * @return The time difference between the current time and the start time.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
boost::posix_time::time_duration TimeKeeper::since(ptime now) const
{
    return now - start_time();
}

/**
 * @brief Returns the event at the specified index, handling negative indices by wrapping around to the end of the list.
 *
 * @param ind The index of the event to retrieve.
 * @return The event at the specified index.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
TimeKeeper::event TimeKeeper::operator[](int ind) const
{
    while (ind < 0) { ind += m_events.size();}

    return m_events[ind];
}

/**
 * Returns a string summary of all events managed by this TimeKeeper instance.
 *
 * @return A formatted string containing summaries of individual events.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
std::string TimeKeeper::summary() const
{
    stringstream ss;
    for (int ind=0; ind<m_events.size(); ++ind) {
	ss << this->emit(ind) << "\n";
    }
    return ss.str();
}

/**
 * @brief Returns a string representation of the event at the specified index.
 *
 * @param[in] ind Index of the event to retrieve.
 * @return String containing the timestamp and description of the event.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
std::string TimeKeeper::emit(int ind) const
{
    while (ind < 0) { ind += m_events.size();}
    //cerr << "emit " << ind << endl;
    int prev_ind = ind-1;
    if (prev_ind<0) prev_ind=0;
    const event& prev = (*this)[prev_ind];
    const event& evt = (*this)[ind];

    deltat from_start = since(evt.first);
    deltat from_last = evt.first - prev.first;

    stringstream ss;
    ss << "TICK: " << from_start.total_milliseconds() << " ms "
       << "(this: " << from_last.total_milliseconds() << " ms) "
       << evt.second;
    return ss.str();
}
